use crate::{DirInfo, FileInfo};
use chrono::{DateTime, Local, LocalResult, TimeZone, Utc};
use dialoguer::Input;
use filesize::file_real_size_fast;
use nu_engine::glob_from;
#[allow(deprecated)]
use nu_engine::{command_prelude::*, env::current_dir, get_eval_expression};
use nu_glob::{MatchOptions, Pattern};
use nu_path::{canonicalize_with, expand_path_with, expand_to_real_path};
use nu_protocol::{DataSource, FromValue, NuGlob, PipelineMetadata, Signals};
use pathdiff::diff_paths;

#[cfg(unix)]
use std::os::unix::fs::PermissionsExt;
use std::{
    error::Error,
    path::{Path, PathBuf},
    time::{SystemTime, UNIX_EPOCH},
};

#[derive(Clone)]
pub struct Ls {
    pub(crate) all_entries: bool,
    pub(crate) long_format: bool,
    pub(crate) short_names: bool,
    pub(crate) full_paths: bool,
    pub(crate) calculate_du: bool,
    pub(crate) directory_only: bool,
    pub(crate) use_mime_type: bool,
    pub(crate) listing_span: Span,
    pub(crate) min_size: Option<u64>,
    pub(crate) deref_links: bool,
    pub(crate) exclude_pattern: Option<Pattern>,
    pub(crate) include_all_files: bool,
    pub(crate) scan_span: Span,
    pub(crate) glob_expand: bool,
    pub(crate) recursive_hidden: bool,
    pub(crate) strict_expand: bool,
    pub(crate) follow_symlink: bool,
    pub(crate) expand_cwd: String,
    pub(crate) raw_open: bool,
    pub(crate) interactive: bool,
}

impl Default for Ls {
    fn default() -> Self {
        Self {
            all_entries: false,
            long_format: false,
            short_names: false,
            full_paths: false,
            calculate_du: false,
            directory_only: false,
            use_mime_type: false,
            listing_span: Span::unknown(),
            min_size: None,
            deref_links: false,
            exclude_pattern: None,
            include_all_files: false,
            scan_span: Span::unknown(),
            glob_expand: true,
            recursive_hidden: false,
            strict_expand: false,
            follow_symlink: true,
            expand_cwd: String::new(),
            raw_open: false,
            interactive: false,
        }
    }
}

const GLOB_CHARS: &[char] = &['*', '?', '['];

impl Command for Ls {
    fn name(&self) -> &str {
        "ls"
    }

    fn usage(&self) -> &str {
        "List the filenames, sizes, and modification times of items in a directory."
    }

    fn search_terms(&self) -> Vec<&str> {
        vec!["dir"]
    }

    fn signature(&self) -> nu_protocol::Signature {
        Signature::build("ls")
            .input_output_types(vec![(Type::Nothing, Type::table())])
            // LsGlobPattern is similar to string, it won't auto-expand
            // and we use it to track if the user input is quoted.
            .rest("pattern", SyntaxShape::OneOf(vec![SyntaxShape::GlobPattern, SyntaxShape::String]), "The glob pattern to use.")
            .switch("all", "Show hidden files", Some('a'))
            .switch(
                "long",
                "Get all available columns for each entry (slower; columns are platform-dependent)",
                Some('l'),
            )
            .switch(
                "short-names",
                "Only print the file names, and not the path",
                Some('s'),
            )
            .switch("full-paths", "display paths as absolute paths", Some('f'))
            .switch(
                "du",
                "Display the apparent directory size (\"disk usage\") in place of the directory metadata size",
                Some('d'),
            )
            .switch(
                "directory",
                "List the specified directory itself instead of its contents",
                Some('D'),
            )
            .switch("mime-type", "Show mime-type in type column instead of 'file' (based on filenames only; files' contents are not examined)", Some('m'))
            .category(Category::FileSystem)
    }

    fn run(
        &self,
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
        _input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let lister = Ls {
            all_entries: call.has_flag(engine_state, stack, "all")?,
            long_format: call.has_flag(engine_state, stack, "long")?,
            short_names: call.has_flag(engine_state, stack, "short-names")?,
            full_paths: call.has_flag(engine_state, stack, "full-paths")?,
            calculate_du: call.has_flag(engine_state, stack, "du")?,
            directory_only: call.has_flag(engine_state, stack, "directory")?,
            use_mime_type: call.has_flag(engine_state, stack, "mime-type")?,
            listing_span: call.head,
            ..Ls::default()
        };
        lister.execute_listing(engine_state, stack, call)
    }

    fn examples(&self) -> Vec<Example> {
        vec![
            Example {
                description: "List visible files in the current directory",
                example: "ls",
                result: None,
            },
            Example {
                description: "List visible files in a subdirectory",
                example: "ls subdir",
                result: None,
            },
            Example {
                description: "List visible files with full path in the parent directory",
                example: "ls -f ..",
                result: None,
            },
            Example {
                description: "List Rust files",
                example: "ls *.rs",
                result: None,
            },
            Example {
                description: "List files and directories whose name do not contain 'bar'",
                example: "ls | where name !~ bar",
                result: None,
            },
            Example {
                description: "List the full path of all dirs in your home directory",
                example: "ls -a ~ | where type == dir",
                result: None,
            },
            Example {
                description:
                    "List only the names (not paths) of all dirs in your home directory which have not been modified in 7 days",
                example: "ls -as ~ | where type == dir and modified < ((date now) - 7day)",
                result: None,
            },
            Example {
                description:
                    "Recursively list all files and subdirectories under the current directory using a glob pattern",
                example: "ls -a **/*",
                result: None,
            },
            Example {
                description:
                    "Recursively list *.rs and *.toml files using the glob command",
                example: "ls ...(glob **/*.{rs,toml})",
                result: None,
            },
            Example {
                description: "List given paths and show directories themselves",
                example: "['/path/to/directory' '/path/to/file'] | each {|| ls -D $in } | flatten",
                result: None,
            },
        ]
    }}

impl Ls {
    fn execute_listing(
        &self,
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
    ) -> Result<PipelineData, ShellError> {
        let call_span = self.listing_span;
        #[allow(deprecated)]
        let cwd = current_dir(engine_state, stack)?;

        let pattern_arg = self.collect_glob_patterns(engine_state, stack, call, 0)?;
        let input_pattern_arg = if !call.has_positional_args(stack, 0) {
            None
        } else {
            Some(pattern_arg)
        };
        match input_pattern_arg {
            None => Ok(self
                .ls_for_one_pattern(None, engine_state.signals(), cwd)?
                .into_pipeline_data_with_metadata(
                    call_span,
                    engine_state.signals().clone(),
                    PipelineMetadata {
                        data_source: DataSource::Ls,
                        content_type: None,
                    },
                )),
            Some(pattern) => {
                let mut result_iters = vec![];
                for pat in pattern {
                    result_iters.push(self.ls_for_one_pattern(
                        Some(pat),
                        engine_state.signals(),
                        cwd.clone(),
                    )?)
                }

                Ok(result_iters
                    .into_iter()
                    .flatten()
                    .into_pipeline_data_with_metadata(
                        call_span,
                        engine_state.signals().clone(),
                        PipelineMetadata {
                            data_source: DataSource::Ls,
                            content_type: None,
                        },
                    ))
            }
        }
    }

    fn ls_for_one_pattern(
        &self,
        pattern_arg: Option<Spanned<NuGlob>>,
        signals: &Signals,
        cwd: PathBuf,
    ) -> Result<Box<dyn Iterator<Item = Value> + Send>, ShellError> {
        let all = self.all_entries;
        let directory = self.directory_only;
        let call_span = self.listing_span;
        let lister = self.clone();
        let pattern_arg = {
            if let Some(path) = pattern_arg {
                if path.item.as_ref().is_empty() {
                    return Err(ShellError::FileNotFoundCustom {
                        msg: "empty string('') directory or file does not exist".to_string(),
                        span: path.span,
                    });
                }
                match path.item {
                    NuGlob::DoNotExpand(p) => Some(Spanned {
                        item: NuGlob::DoNotExpand(nu_utils::strip_ansi_string_unlikely(p)),
                        span: path.span,
                    }),
                    NuGlob::Expand(p) => Some(Spanned {
                        item: NuGlob::Expand(nu_utils::strip_ansi_string_unlikely(p)),
                        span: path.span,
                    }),
                }
            } else {
                pattern_arg
            }
        };

        let mut just_read_dir = false;
        let p_tag: Span = pattern_arg.as_ref().map(|p| p.span).unwrap_or(call_span);
        let (pattern_arg, absolute_path) = match pattern_arg {
            Some(pat) => {
                let tmp_expanded =
                    nu_path::expand_path_with(pat.item.as_ref(), &cwd, pat.item.is_expand());
                if !directory && tmp_expanded.is_dir() {
                    if permission_denied(&tmp_expanded) {
                        return Err(self.permission_denied_error(&tmp_expanded, p_tag));
                    }
                    if is_empty_dir(&tmp_expanded) {
                        return Ok(Box::new(vec![].into_iter()));
                    }
                    just_read_dir = !(pat.item.is_expand() && pat.item.as_ref().contains(GLOB_CHARS));
                }

                let absolute_path = Path::new(pat.item.as_ref()).is_absolute()
                    || (pat.item.is_expand() && expand_to_real_path(pat.item.as_ref()).is_absolute());
                (pat.item, absolute_path)
            }
            None => {
                if directory {
                    (NuGlob::Expand(".".to_string()), false)
                } else if is_empty_dir(&cwd) {
                    return Ok(Box::new(vec![].into_iter()));
                } else {
                    (NuGlob::Expand("*".to_string()), false)
                }
            }
        };

        let hidden_dir_specified = is_hidden_dir(pattern_arg.as_ref());
        let path = pattern_arg.into_spanned(p_tag);
        let (prefix, paths) = if just_read_dir {
            let expanded = nu_path::expand_path_with(path.item.as_ref(), &cwd, path.item.is_expand());
            let paths = read_dir(&expanded)?;
            (Some(expanded), paths)
        } else {
            let glob_options = if all {
                None
            } else {
                let glob_options = MatchOptions {
                    recursive_match_hidden_dir: false,
                    ..Default::default()
                };
                Some(glob_options)
            };
            glob_from(&path, &cwd, call_span, glob_options)?
        };

        let mut paths_peek = paths.peekable();
        if paths_peek.peek().is_none() {
            return Err(self.no_matches_error(&path.item, p_tag));
        }

        let mut hidden_dirs = vec![];

        let signals = signals.clone();
        Ok(Box::new(paths_peek.filter_map(move |x| match x {
            Ok(path) => {
                let metadata = match std::fs::symlink_metadata(&path) {
                    Ok(metadata) => Some(metadata),
                    Err(_) => None,
                };
                if path_contains_hidden_folder(&path, &hidden_dirs) {
                    return None;
                }

                if !all && !hidden_dir_specified && is_hidden_dir(&path) {
                    if path.is_dir() {
                        hidden_dirs.push(path);
                    }
                    return None;
                }

                let display_name = lister
                    .format_display_name(&path, &cwd, prefix.as_deref(), absolute_path);

                match display_name {
                    Ok(name) => {
                        let entry = lister.dir_entry_dict(
                            &path,
                            &name,
                            metadata.as_ref(),
                            call_span,
                            &signals,
                        );
                        match entry {
                            Ok(value) => Some(value),
                            Err(err) => Some(Value::error(err, call_span)),
                        }
                    }
                    Err(err) => Some(Value::error(err, call_span)),
                }
            }
            Err(err) => Some(Value::error(err, call_span)),
        })))
    }

    fn format_display_name(
        &self,
        path: &Path,
        cwd: &Path,
        prefix: Option<&Path>,
        absolute_path: bool,
    ) -> Result<String, ShellError> {
        let span = self.listing_span;
        let name = if self.short_names {
            path.file_name().map(|os| os.to_string_lossy().to_string())
        } else if self.full_paths || absolute_path {
            Some(path.to_string_lossy().to_string())
        } else if let Some(prefix) = prefix {
            if let Ok(remainder) = path.strip_prefix(prefix) {
                if self.directory_only {
                    let path_diff = if let Some(path_diff_not_dot) = diff_paths(path, cwd) {
                        let path_diff_not_dot = path_diff_not_dot.to_string_lossy();
                        if path_diff_not_dot.is_empty() {
                            ".".to_string()
                        } else {
                            path_diff_not_dot.to_string()
                        }
                    } else {
                        path.to_string_lossy().to_string()
                    };
                    Some(path_diff)
                } else {
                    let new_prefix = if let Some(pfx) = diff_paths(prefix, cwd) {
                        pfx
                    } else {
                        prefix.to_path_buf()
                    };
                    Some(new_prefix.join(remainder).to_string_lossy().to_string())
                }
            } else {
                Some(path.to_string_lossy().to_string())
            }
        } else {
            Some(path.to_string_lossy().to_string())
        };
        name.ok_or_else(|| ShellError::GenericError {
            error: format!("Invalid file name: {:}", path.to_string_lossy()),
            msg: "invalid file name".into(),
            span: Some(span),
            help: None,
            inner: vec![],
        })
    }

    pub(crate) fn dir_entry_dict(
        &self,
        filename: &std::path::Path,
        display_name: &str,
        metadata: Option<&std::fs::Metadata>,
        span: Span,
        signals: &Signals,
    ) -> Result<Value, ShellError> {
        let span = if self.listing_span != Span::unknown() {
            self.listing_span
        } else {
            span
        };
        let long = self.long_format;
        #[cfg(windows)]
        if metadata.is_none() {
            return Ok(windows_helper::dir_entry_dict_windows_fallback(
                filename,
                display_name,
                span,
                long,
            ));
        }

        let mut record = Record::new();
        let mut file_type = "unknown".to_string();

        record.push("name", Value::string(display_name, span));

        if let Some(md) = metadata {
            let type_value = self.classify_listing_type_value(md, display_name);
            if let Value::String { val, .. } = &type_value {
                file_type = val.clone();
            }
            record.push("type", type_value);
        } else {
            record.push("type", Value::nothing(span));
        }

        if long {
            if let Some(md) = metadata {
                record.push("target", self.symlink_target_value(filename, md, span));
            }
        }

        if long {
            if let Some(md) = metadata {
                record.push("readonly", Value::bool(md.permissions().readonly(), span));

                #[cfg(unix)]
                {
                    use nu_utils::filesystem::users;
                    use std::os::unix::fs::MetadataExt;

                    let mode = md.permissions().mode();
                    record.push(
                        "mode",
                        Value::string(umask::Mode::from(mode).to_string(), span),
                    );

                    let nlinks = md.nlink();
                    record.push("num_links", Value::int(nlinks as i64, span));

                    let inode = md.ino();
                    record.push("inode", Value::int(inode as i64, span));

                    record.push(
                        "user",
                        if let Some(user) = users::get_user_by_uid(md.uid().into()) {
                            Value::string(user.name, span)
                        } else {
                            Value::int(md.uid().into(), span)
                        },
                    );

                    record.push(
                        "group",
                        if let Some(group) = users::get_group_by_gid(md.gid().into()) {
                            Value::string(group.name, span)
                        } else {
                            Value::int(md.gid().into(), span)
                        },
                    );
                }
            }
        }

        record.push(
            "size",
            self.size_for_entry(filename, metadata, &file_type, span, signals)?,
        );

        if let Some(md) = metadata {
            let (created, accessed, modified) = self.build_metadata_times(md, span);
            if long {
                record.push("created", created);
                record.push("accessed", accessed);
            }
            record.push("modified", modified);
        } else {
            if long {
                record.push("created", Value::nothing(span));
                record.push("accessed", Value::nothing(span));
            }
            record.push("modified", Value::nothing(span));
        }

        Ok(Value::record(record, span))
    }

    fn symlink_target_value(
        &self,
        filename: &Path,
        md: &std::fs::Metadata,
        span: Span,
    ) -> Value {
        let span = if self.listing_span != Span::unknown() {
            self.listing_span
        } else {
            span
        };
        if md.file_type().is_symlink() {
            if let Ok(path_to_link) = filename.read_link() {
                Value::string(path_to_link.to_string_lossy(), span)
            } else {
                Value::string("Could not obtain target file's path", span)
            }
        } else {
            Value::nothing(span)
        }
    }

    fn size_for_entry(
        &self,
        filename: &Path,
        metadata: Option<&std::fs::Metadata>,
        file_type: &str,
        span: Span,
        signals: &Signals,
    ) -> Result<Value, ShellError> {
        let span = if self.listing_span != Span::unknown() {
            self.listing_span
        } else {
            span
        };
        if let Some(md) = metadata {
            let zero_sized = file_type == "pipe"
                || file_type == "socket"
                || file_type == "char device"
                || file_type == "block device";

            if md.is_dir() {
                self.directory_size_value(filename, md, span, signals)
            } else if md.is_file() {
                Ok(Value::filesize(md.len() as i64, span))
            } else if md.file_type().is_symlink() {
                if let Ok(symlink_md) = filename.symlink_metadata() {
                    Ok(Value::filesize(symlink_md.len() as i64, span))
                } else {
                    Ok(Value::nothing(span))
                }
            } else if zero_sized {
                Ok(Value::filesize(0, span))
            } else {
                Ok(Value::nothing(span))
            }
        } else {
            Ok(Value::nothing(span))
        }
    }

    fn directory_size_value(
        &self,
        filename: &Path,
        md: &std::fs::Metadata,
        span: Span,
        signals: &Signals,
    ) -> Result<Value, ShellError> {
        let span = if self.listing_span != Span::unknown() {
            self.listing_span
        } else {
            span
        };
        if self.calculate_du {
            let dir_size = Ls {
                min_size: None,
                deref_links: false,
                exclude_pattern: None,
                include_all_files: false,
                scan_span: Span::new(0, 2),
                ..Ls::default()
            }
            .collect_dir_info(filename.to_path_buf(), None, span, signals)?
            .get_size();
            Ok(Value::filesize(dir_size as i64, span))
        } else {
            Ok(Value::filesize(md.len() as i64, span))
        }
    }

    fn build_metadata_times(
        &self,
        md: &std::fs::Metadata,
        span: Span,
    ) -> (Value, Value, Value) {
        let span = if self.listing_span != Span::unknown() {
            self.listing_span
        } else {
            span
        };
        let created = {
            let mut val = Value::nothing(span);
            if self.long_format {
                if let Ok(c) = md.created() {
                    if let Some(local) = try_convert_to_local_date_time(c) {
                        val = Value::date(local.with_timezone(local.offset()), span);
                    }
                }
            }
            val
        };
        let accessed = {
            let mut val = Value::nothing(span);
            if self.long_format {
                if let Ok(a) = md.accessed() {
                    if let Some(local) = try_convert_to_local_date_time(a) {
                        val = Value::date(local.with_timezone(local.offset()), span);
                    }
                }
            }
            val
        };
        let modified = {
            let mut val = Value::nothing(span);
            if let Ok(m) = md.modified() {
                if let Some(local) = try_convert_to_local_date_time(m) {
                    val = Value::date(local.with_timezone(local.offset()), span);
                }
            }
            val
        };
        (created, accessed, modified)
    }

    fn permission_denied_error(&self, path: &Path, span: Span) -> ShellError {
        let span = if self.listing_span != Span::unknown() {
            self.listing_span
        } else {
            span
        };
        #[cfg(unix)]
        let error_msg = format!(
            "The permissions of {:o} do not allow access for this user",
            path.metadata()
                .map(|md| md.permissions().mode() & 0o0777)
                .unwrap_or(0)
        );
        #[cfg(not(unix))]
        let error_msg = {
            let _ = path;
            String::from("Permission denied")
        };
        ShellError::GenericError {
            error: "Permission denied".into(),
            msg: error_msg,
            span: Some(span),
            help: None,
            inner: vec![],
        }
    }

    fn no_matches_error(&self, pattern: &NuGlob, span: Span) -> ShellError {
        let span = if self.listing_span != Span::unknown() {
            self.listing_span
        } else {
            span
        };
        ShellError::GenericError {
            error: format!("No matches found for {:?}", pattern),
            msg: "Pattern, file or folder not found".into(),
            span: Some(span),
            help: Some("no matches found".into()),
            inner: vec![],
        }
    }

    fn classify_listing_type_value(
        &self,
        md: &std::fs::Metadata,
        display_name: &str,
    ) -> Value {
        Value::string(
            get_file_type(md, display_name, self.use_mime_type),
            self.listing_span,
        )
    }

    pub(crate) fn collect_dir_info(
        &self,
        path: PathBuf,
        depth: Option<u64>,
        span: Span,
        signals: &Signals,
    ) -> Result<DirInfo, ShellError> {
        let tag = self.scan_span;
        let mut info = self.build_empty_dir_info(path, tag);

        match std::fs::metadata(info.path()) {
            Ok(d) => {
                let size = d.len();
                let blocks = file_real_size_fast(info.path(), &d).ok().unwrap_or(0);
                info.set_size(size, blocks);
            }
            Err(e) => info = self.record_scan_error(info, e.into()),
        };

        match std::fs::read_dir(info.path()) {
            Ok(d) => {
                for f in d {
                    signals.check(span)?;
                    match f {
                        Ok(i) => match self.scan_path_kind(&i.path()) {
                            Ok(t) if t.is_dir() => {
                                info = self.add_scanned_directory(
                                    info,
                                    i.path(),
                                    depth,
                                    span,
                                    signals,
                                )?
                            }
                            Ok(_t) => info = self.add_scanned_file(info, i.path()),
                            Err(e) => info = self.record_scan_error(info, e),
                        },
                        Err(e) => info = self.record_scan_error(info, e.into()),
                    }
                }
            }
            Err(e) => info = self.record_scan_error(info, e.into()),
        }
        Ok(info)
    }

    fn add_scanned_directory(
        &self,
        mut info: DirInfo,
        path: PathBuf,
        mut depth: Option<u64>,
        span: Span,
        signals: &Signals,
    ) -> Result<DirInfo, ShellError> {
        let span = if span == Span::unknown() {
            self.scan_span
        } else {
            span
        };
        if let Some(current) = depth {
            if let Some(new) = current.checked_sub(1) {
                depth = Some(new);
            } else {
                return Ok(info);
            }
        }

        let child = self.collect_dir_info(path, depth, span, signals)?;
        info = self.merge_child_dir(info, child);
        Ok(info)
    }

    fn add_scanned_file(&self, mut info: DirInfo, path: PathBuf) -> DirInfo {
        let tag = self.scan_span;
        let include = self
            .exclude_pattern
            .as_ref()
            .map_or(true, |x| !x.matches_path(&path));
        if include {
            match self.collect_file_info(path) {
                Ok(file) => {
                    info = self.apply_size_and_store(info, file, tag);
                }
                Err(e) => info = self.record_scan_error(info, e),
            }
        }
        info
    }

    pub(crate) fn collect_file_info(&self, path: PathBuf) -> Result<FileInfo, ShellError> {
        let tag = self.scan_span;
        let d = self.deref_or_symlink_meta(&path)?;
        let block_size = file_real_size_fast(&path, &d).ok();
        Ok(FileInfo::from_parts(path, d.len(), block_size, tag))
    }

    fn read_scan_metadata(&self, path: &Path) -> Result<std::fs::Metadata, ShellError> {
        let m = if self.deref_links {
            std::fs::metadata(path)
        } else {
            std::fs::symlink_metadata(path)
        };
        match m {
            Ok(d) => Ok(d),
            Err(e) => {
                if self.scan_span == Span::unknown() {
                    Err(e.into())
                } else {
                    Err(e.into())
                }
            }
        }
    }

    fn record_scan_error(&self, mut info: DirInfo, error: ShellError) -> DirInfo {
        if self.scan_span != Span::unknown() {
            info.push_error(error);
        } else {
            info.push_error(error);
        }
        info
    }

    fn apply_size_and_store(&self, mut info: DirInfo, file: FileInfo, tag: Span) -> DirInfo {
        let inc = self.min_size.map_or(true, |s| file.size() >= s);
        if inc {
            info.absorb_file_data(file.size(), file.blocks());
            if self.include_all_files {
                info.push_file(file);
            }
        }
        if tag != self.scan_span && self.scan_span == Span::unknown() {
            return info;
        }
        info
    }

    fn scan_path_kind(&self, path: &Path) -> Result<std::fs::FileType, ShellError> {
        match std::fs::symlink_metadata(path) {
            Ok(md) => Ok(md.file_type()),
            Err(e) => {
                if self.scan_span == Span::unknown() {
                    Err(e.into())
                } else {
                    Err(e.into())
                }
            }
        }
    }

    fn build_empty_dir_info(&self, path: PathBuf, tag: Span) -> DirInfo {
        let scan_tag = if tag == Span::unknown() {
            self.scan_span
        } else {
            self.scan_span
        };
        DirInfo::empty(path, scan_tag)
    }

    fn merge_child_dir(&self, mut info: DirInfo, child: DirInfo) -> DirInfo {
        if self.scan_span != Span::unknown() || child.get_size() > 0 {
            info.absorb_dir(child);
        } else {
            info.absorb_dir(child);
        }
        info
    }

    fn deref_or_symlink_meta(&self, path: &Path) -> Result<std::fs::Metadata, ShellError> {
        match self.read_scan_metadata(path) {
            Ok(md) => Ok(md),
            Err(err) => {
                if self.scan_span == Span::unknown() {
                    Err(err)
                } else {
                    Err(err)
                }
            }
        }
    }

    pub(crate) fn expand_path_value(&self, path: &Path, span: Span) -> Value {
        if self.strict_expand {
            self.expand_strict_path(path, span)
        } else if !self.follow_symlink {
            Value::string(
                expand_path_with(path, &self.expand_cwd, true).to_string_lossy(),
                span,
            )
        } else {
            self.expand_relaxed_path(path, span)
        }
    }

    pub(crate) fn expand_user_path(&self, path: &Path) -> PathBuf {
        expand_path_with(path, &self.expand_cwd, true)
    }

    fn canonicalize_user_path(&self, path: &Path) -> Result<PathBuf, std::io::Error> {
        canonicalize_with(path, &self.expand_cwd)
    }

    fn expand_strict_path(&self, path: &Path, span: Span) -> Value {
        if self.expand_cwd.is_empty() && path.as_os_str().is_empty() {
            return self.resolve_expand_failure(span);
        }
        match self.canonicalize_user_path(path) {
            Ok(p) => {
                if !self.follow_symlink {
                    self.expand_without_symlink_follow(path, span)
                } else {
                    self.expand_path_lossy_string(&p, span)
                }
            }
            Err(_) => self.resolve_expand_failure(span),
        }
    }

    fn expand_relaxed_path(&self, path: &Path, span: Span) -> Value {
        match canonicalize_with(path, &self.expand_cwd) {
            Ok(p) => self.expand_path_lossy_string(&p, span),
            Err(_) => {
                let expanded = expand_path_with(path, &self.expand_cwd, true);
                self.expand_path_lossy_string(&expanded, span)
            }
        }
    }

    fn expand_without_symlink_follow(&self, path: &Path, span: Span) -> Value {
        let expanded = expand_path_with(path, &self.expand_cwd, true);
        self.expand_path_lossy_string(&expanded, span)
    }

    fn resolve_expand_failure(&self, span: Span) -> Value {
        let help = if self.expand_cwd.is_empty() {
            Some("set a working directory before expanding the path".into())
        } else {
            None
        };
        Value::error(
            ShellError::GenericError {
                error: "Could not expand path".into(),
                msg: "could not be expanded (path might not exist, non-final \
                        component is not a directory, or other cause)"
                    .into(),
                span: Some(span),
                help,
                inner: vec![],
            },
            span,
        )
    }

    fn expand_path_lossy_string(&self, path: &Path, span: Span) -> Value {
        if self.expand_cwd.is_empty() && path.is_relative() {
            Value::string(path.to_string_lossy(), span)
        } else {
            Value::string(path.to_string_lossy(), span)
        }
    }

    pub(crate) fn expand_path_buf(&self, path: &Path) -> PathBuf {
        self.expand_user_path(path)
    }

    pub(crate) fn classify_expanded_path(&self, path: &Path, span: Span) -> Value {
        let expanded = if path.is_absolute() {
            path.to_path_buf()
        } else {
            expand_path_with(path, &self.expand_cwd, true)
        };
        match expanded.symlink_metadata() {
            Ok(metadata) => Value::string(path_kind_from_metadata(&metadata), span),
            Err(err) if err.kind() == std::io::ErrorKind::NotFound => Value::nothing(span),
            Err(err) => Value::error(err.into_spanned(span).into(), span),
        }
    }

    pub(crate) fn collect_glob_patterns(
        &self,
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
        starting_pos: usize,
    ) -> Result<Vec<Spanned<NuGlob>>, ShellError> {
        let eval_expression = get_eval_expression(engine_state);
        call.rest_iter_flattened(engine_state, stack, eval_expression, starting_pos)?
            .into_iter()
            .map(|value| {
                let glob = self.normalize_glob_value(value)?;
                if self.glob_expand {
                    Ok(glob)
                } else {
                    Ok(self.interpret_glob_item(glob))
                }
            })
            .collect()
    }

    fn interpret_glob_item(&self, glob: Spanned<NuGlob>) -> Spanned<NuGlob> {
        if self.glob_expand {
            glob
        } else {
            Spanned {
                item: NuGlob::DoNotExpand(glob.item.as_ref().to_string()),
                span: glob.span,
            }
        }
    }

    fn glob_match_options(&self) -> Option<MatchOptions> {
        if self.glob_expand && !self.recursive_hidden {
            Some(MatchOptions {
                recursive_match_hidden_dir: false,
                ..Default::default()
            })
        } else {
            None
        }
    }

    fn normalize_glob_value(&self, value: Value) -> Result<Spanned<NuGlob>, ShellError> {
        let glob = Spanned::<NuGlob>::from_value(value)?;
        if self.glob_expand {
            Ok(glob)
        } else {
            Ok(self.interpret_glob_item(glob))
        }
    }

    fn glob_prefix_paths(
        &self,
        path: &Spanned<NuGlob>,
        cwd: &Path,
        span: Span,
    ) -> Result<
        (
            Option<PathBuf>,
            Box<dyn Iterator<Item = Result<PathBuf, ShellError>> + Send>,
        ),
        ShellError,
    > {
        let options = self.glob_match_options();
        if self.glob_expand {
            glob_from(path, cwd, span, options)
        } else {
            let expanded = expand_path_with(path.item.as_ref(), cwd, false);
            let paths = read_dir(&expanded)?;
            Ok((Some(expanded), paths))
        }
    }

    pub(crate) fn configured_glob_from(
        &self,
        path: &Spanned<NuGlob>,
        cwd: &Path,
        span: Span,
    ) -> Result<Box<dyn Iterator<Item = Result<PathBuf, ShellError>> + Send>, ShellError> {
        if !self.glob_expand && path.item.as_ref().is_empty() {
            return Ok(Box::new(std::iter::empty()));
        }
        Ok(self.glob_prefix_paths(path, cwd, span)?.1)
    }

    pub(crate) fn detect_open_content_type(&self, extension: &str) -> Option<String> {
        if !self.raw_open {
            return None;
        }
        match extension {
            "yaml" | "yml" => Some("application/yaml".to_string()),
            _ => mime_guess::from_ext(extension)
                .first()
                .map(|mime| mime.to_string()),
        }
    }

    pub(crate) fn extensions_for_converter(&self, filename: &str) -> Option<Vec<String>> {
        if self.raw_open {
            None
        } else {
            Some(extract_extensions_inner(filename))
        }
    }

    pub(crate) fn content_type_from_path(&self, path: &Path) -> Option<String> {
        if !self.raw_open {
            return None;
        }
        path.extension()
            .map(|ext| ext.to_string_lossy().to_string())
            .and_then(|s| self.detect_open_content_type(&s))
    }

    pub(crate) fn open_metadata_plan(&self, path: &Path) -> (Option<String>, Option<Vec<String>>) {
        let content_type = self.content_type_from_path(path);
        let exts = if self.raw_open {
            None
        } else {
            let path_str = path
                .file_name()
                .unwrap_or_else(|| std::ffi::OsStr::new(path))
                .to_string_lossy()
                .to_lowercase();
            self.extensions_for_converter(path_str.as_str())
        };
        (content_type, exts)
    }

    pub(crate) fn try_interaction_outcome(
        &self,
        prompt: String,
    ) -> (Result<Option<bool>, Box<dyn Error>>, bool) {
        let interaction = if self.interactive {
            match self.prompt_for_confirmation(prompt) {
                Ok(i) => Ok(Some(i)),
                Err(e) => Err(e),
            }
        } else {
            Ok(None)
        };

        let confirmed = match &interaction {
            Ok(maybe_input) => maybe_input.unwrap_or(false),
            Err(_) => false,
        };

        (interaction, confirmed)
    }

    fn prompt_for_confirmation(&self, prompt: String) -> Result<bool, Box<dyn Error>> {
        if !self.interactive {
            return Ok(false);
        }
        let input = Input::new()
            .with_prompt(prompt)
            .validate_with(|c_input: &String| -> Result<(), String> {
                if c_input.len() == 1
                    && (c_input == "y" || c_input == "Y" || c_input == "n" || c_input == "N")
                {
                    Ok(())
                } else if c_input.len() > 1 {
                    Err("Enter only one letter (Y/N)".to_string())
                } else {
                    Err("Input not valid".to_string())
                }
            })
            .default("Y/N".into())
            .interact_text()?;
        self.parse_confirmation_input(input)
    }

    fn parse_confirmation_input(&self, input: String) -> Result<bool, Box<dyn Error>> {
        if !self.interactive {
            return Ok(false);
        }
        if input == "y" || input == "Y" {
            Ok(true)
        } else {
            Ok(false)
        }
    }
}

fn extract_extensions_inner(filename: &str) -> Vec<String> {
    let parts: Vec<&str> = filename.split('.').collect();
    let mut extensions: Vec<String> = Vec::new();
    let mut current_extension = String::new();

    for part in parts.iter().rev() {
        if current_extension.is_empty() {
            current_extension.push_str(part);
        } else {
            current_extension = format!("{}.{}", part, current_extension);
        }
        extensions.push(current_extension.clone());
    }

    extensions.pop();
    extensions.reverse();
    extensions
}

fn path_kind_from_metadata(md: &std::fs::Metadata) -> &'static str {
    let ft = md.file_type();
    let mut file_type = "unknown";
    if ft.is_dir() {
        file_type = "dir";
    } else if ft.is_file() {
        file_type = "file";
    } else if ft.is_symlink() {
        file_type = "symlink";
    } else {
        #[cfg(unix)]
        {
            use std::os::unix::fs::FileTypeExt;
            if ft.is_block_device() {
                file_type = "block device";
            } else if ft.is_char_device() {
                file_type = "char device";
            } else if ft.is_fifo() {
                file_type = "pipe";
            } else if ft.is_socket() {
                file_type = "socket";
            }
        }
    }
    file_type
}

fn permission_denied(dir: impl AsRef<Path>) -> bool {
    match dir.as_ref().read_dir() {
        Err(e) => matches!(e.kind(), std::io::ErrorKind::PermissionDenied),
        Ok(_) => false,
    }
}

fn is_empty_dir(dir: impl AsRef<Path>) -> bool {
    match dir.as_ref().read_dir() {
        Err(_) => true,
        Ok(mut s) => s.next().is_none(),
    }
}

fn is_hidden_dir(dir: impl AsRef<Path>) -> bool {
    #[cfg(windows)]
    {
        use std::os::windows::fs::MetadataExt;

        if let Ok(metadata) = dir.as_ref().metadata() {
            let attributes = metadata.file_attributes();
            (attributes & 0x2) != 0
        } else {
            false
        }
    }

    #[cfg(not(windows))]
    {
        dir.as_ref()
            .file_name()
            .map(|name| name.to_string_lossy().starts_with('.'))
            .unwrap_or(false)
    }
}

fn path_contains_hidden_folder(path: &Path, folders: &[PathBuf]) -> bool {
    if folders.iter().any(|p| path.starts_with(p.as_path())) {
        return true;
    }
    false
}

#[cfg(unix)]
use std::os::unix::fs::FileTypeExt;

pub fn get_file_type(md: &std::fs::Metadata, display_name: &str, use_mime_type: bool) -> String {
    let ft = md.file_type();
    let mut file_type = "unknown";
    if ft.is_dir() {
        file_type = "dir";
    } else if ft.is_file() {
        file_type = "file";
    } else if ft.is_symlink() {
        file_type = "symlink";
    } else {
        #[cfg(unix)]
        {
            if ft.is_block_device() {
                file_type = "block device";
            } else if ft.is_char_device() {
                file_type = "char device";
            } else if ft.is_fifo() {
                file_type = "pipe";
            } else if ft.is_socket() {
                file_type = "socket";
            }
        }
    }
    if use_mime_type {
        let guess = mime_guess::from_path(display_name);
        let mime_guess = match guess.first() {
            Some(mime_type) => mime_type.essence_str().to_string(),
            None => "unknown".to_string(),
        };
        if file_type == "file" {
            mime_guess
        } else {
            file_type.to_string()
        }
    } else {
        file_type.to_string()
    }
}


// TODO: can we get away from local times in `ls`? internals might be cleaner if we worked in UTC
// and left the conversion to local time to the display layer
fn try_convert_to_local_date_time(t: SystemTime) -> Option<DateTime<Local>> {
    // Adapted from https://github.com/chronotope/chrono/blob/v0.4.19/src/datetime.rs#L755-L767.
    let (sec, nsec) = match t.duration_since(UNIX_EPOCH) {
        Ok(dur) => (dur.as_secs() as i64, dur.subsec_nanos()),
        Err(e) => {
            // unlikely but should be handled
            let dur = e.duration();
            let (sec, nsec) = (dur.as_secs() as i64, dur.subsec_nanos());
            if nsec == 0 {
                (-sec, 0)
            } else {
                (-sec - 1, 1_000_000_000 - nsec)
            }
        }
    };

    const NEG_UNIX_EPOCH: i64 = -11644473600; // t was invalid 0, UNIX_EPOCH subtracted above.
    if sec == NEG_UNIX_EPOCH {
        // do not tz lookup invalid SystemTime
        return None;
    }
    match Utc.timestamp_opt(sec, nsec) {
        LocalResult::Single(t) => Some(t.with_timezone(&Local)),
        _ => None,
    }
}

// #[cfg(windows)] is just to make Clippy happy, remove if you ever want to use this on other platforms
#[cfg(windows)]
fn unix_time_to_local_date_time(secs: i64) -> Option<DateTime<Local>> {
    match Utc.timestamp_opt(secs, 0) {
        LocalResult::Single(t) => Some(t.with_timezone(&Local)),
        _ => None,
    }
}

#[cfg(windows)]
mod windows_helper {
    use super::*;

    use std::os::windows::prelude::OsStrExt;
    use windows::Win32::Foundation::FILETIME;
    use windows::Win32::Storage::FileSystem::{
        FindFirstFileW, FILE_ATTRIBUTE_DIRECTORY, FILE_ATTRIBUTE_READONLY,
        FILE_ATTRIBUTE_REPARSE_POINT, WIN32_FIND_DATAW,
    };
    use windows::Win32::System::SystemServices::{
        IO_REPARSE_TAG_MOUNT_POINT, IO_REPARSE_TAG_SYMLINK,
    };

    /// A secondary way to get file info on Windows, for when std::fs::symlink_metadata() fails.
    /// dir_entry_dict depends on metadata, but that can't be retrieved for some Windows system files:
    /// https://github.com/rust-lang/rust/issues/96980
    pub fn dir_entry_dict_windows_fallback(
        filename: &Path,
        display_name: &str,
        span: Span,
        long: bool,
    ) -> Value {
        let mut record = Record::new();

        record.push("name", Value::string(display_name, span));

        let find_data = match find_first_file(filename, span) {
            Ok(fd) => fd,
            Err(e) => {
                // Sometimes this happens when the file name is not allowed on Windows (ex: ends with a '.', pipes)
                // For now, we just log it and give up on returning metadata columns
                // TODO: find another way to get this data (like cmd.exe, pwsh, and MINGW bash can)
                log::error!("ls: '{}' {}", filename.to_string_lossy(), e);
                return Value::record(record, span);
            }
        };

        record.push(
            "type",
            Value::string(get_file_type_windows_fallback(&find_data), span),
        );

        if long {
            record.push(
                "target",
                if is_symlink(&find_data) {
                    if let Ok(path_to_link) = filename.read_link() {
                        Value::string(path_to_link.to_string_lossy(), span)
                    } else {
                        Value::string("Could not obtain target file's path", span)
                    }
                } else {
                    Value::nothing(span)
                },
            );

            record.push(
                "readonly",
                Value::bool(
                    find_data.dwFileAttributes & FILE_ATTRIBUTE_READONLY.0 != 0,
                    span,
                ),
            );
        }

        let file_size = (find_data.nFileSizeHigh as u64) << 32 | find_data.nFileSizeLow as u64;
        record.push("size", Value::filesize(file_size as i64, span));

        if long {
            record.push("created", {
                let mut val = Value::nothing(span);
                let seconds_since_unix_epoch = unix_time_from_filetime(&find_data.ftCreationTime);
                if let Some(local) = unix_time_to_local_date_time(seconds_since_unix_epoch) {
                    val = Value::date(local.with_timezone(local.offset()), span);
                }
                val
            });

            record.push("accessed", {
                let mut val = Value::nothing(span);
                let seconds_since_unix_epoch = unix_time_from_filetime(&find_data.ftLastAccessTime);
                if let Some(local) = unix_time_to_local_date_time(seconds_since_unix_epoch) {
                    val = Value::date(local.with_timezone(local.offset()), span);
                }
                val
            });
        }

        record.push("modified", {
            let mut val = Value::nothing(span);
            let seconds_since_unix_epoch = unix_time_from_filetime(&find_data.ftLastWriteTime);
            if let Some(local) = unix_time_to_local_date_time(seconds_since_unix_epoch) {
                val = Value::date(local.with_timezone(local.offset()), span);
            }
            val
        });

        Value::record(record, span)
    }

    fn unix_time_from_filetime(ft: &FILETIME) -> i64 {
        /// January 1, 1970 as Windows file time
        const EPOCH_AS_FILETIME: u64 = 116444736000000000;
        const HUNDREDS_OF_NANOSECONDS: u64 = 10000000;

        let time_u64 = ((ft.dwHighDateTime as u64) << 32) | (ft.dwLowDateTime as u64);
        if time_u64 > 0 {
            let rel_to_linux_epoch = time_u64.saturating_sub(EPOCH_AS_FILETIME);
            let seconds_since_unix_epoch = rel_to_linux_epoch / HUNDREDS_OF_NANOSECONDS;
            return seconds_since_unix_epoch as i64;
        }
        0
    }

    // wrapper around the FindFirstFileW Win32 API
    fn find_first_file(filename: &Path, span: Span) -> Result<WIN32_FIND_DATAW, ShellError> {
        unsafe {
            let mut find_data = WIN32_FIND_DATAW::default();
            // The windows crate really needs a nicer way to do string conversions
            let filename_wide: Vec<u16> = filename
                .as_os_str()
                .encode_wide()
                .chain(std::iter::once(0))
                .collect();

            match FindFirstFileW(
                windows::core::PCWSTR(filename_wide.as_ptr()),
                &mut find_data,
            ) {
                Ok(_) => Ok(find_data),
                Err(e) => Err(ShellError::ReadingFile {
                    msg: format!(
                        "Could not read metadata for '{}':\n  '{}'",
                        filename.to_string_lossy(),
                        e
                    ),
                    span,
                }),
            }
        }
    }

    fn get_file_type_windows_fallback(find_data: &WIN32_FIND_DATAW) -> String {
        if find_data.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY.0 != 0 {
            return "dir".to_string();
        }

        if is_symlink(find_data) {
            return "symlink".to_string();
        }

        "file".to_string()
    }

